static inline char *hex_byte_pack_upper(char *buf, u8 byte) /* <=== hex_byte_pack_upper */ 
{
	*buf++ = hex_asc_upper_hi(byte);
	*buf++ = hex_asc_upper_lo(byte);
	return buf;
}

